mapper.select:
SELECT loan_product_id
FROM loan_product
WHERE source_type = #{sourceType}
AND source_product_key = #{sourceProductKey}
LIMIT 1

SELECT loan_product_id AS loanProductId, source_product_key AS sourceProductKey, product_name AS productName, loan_type AS loanType, min_rate AS minRate, max_rate AS maxRate, max_limit_amount AS maxLimitAmount, max_period_months AS maxPeriodMonths, target_description AS targetDescription, active AS active, institution_name AS institutionName, join_way AS joinWay, disclosure_start_date AS disclosureStartDate, disclosure_end_date AS disclosureEndDate, collected_at AS collectedAt, updated_at AS updatedAt FROM loan_product
loan_type = #{loanType}
AND active = #{active}
ORDER BY loan_type ASC, institution_name ASC, product_name ASC, loan_product_id ASC
